1	#!/usr/bin/env bun
2	/**
3	 * inject_loop_continuation.ts — tell a run the loop guard stopped, in its own
4	 * session, what it repeated and that it may take one more turn.
5	 *
6	 * Usage: inject_loop_continuation.ts --session PATH
7	 *
8	 * `domain/work/loop-continuation.ts` decides what is said, from the verdict atoma
9	 * recorded in the session; this puts it where the next turn will read it, as a user
10	 * turn — the same shape `inject_stalled_continuation.ts` writes and for the same
11	 * reason: atoma continues from the session when no prompt is given, so the run sees
12	 * the calls it made and the note after them, then carries on by the documented path.
13	 *
14	 * The verdict is read here rather than passed as arguments because the session is
15	 * where it lives and the run is already going to be read from it. A session with no
16	 * verdict — never written, or written by a binary older than v0.6.0 — has nothing to
17	 * be told, so this says so and appends nothing rather than inventing a note.
18	 */
19	import { existsSync, readFileSync, writeFileSync } from "node:fs";
20	import { parseArgs } from "node:util";
21	import { loopAbortFromSession, loopContinuationMessage } from "../../domain/work/loop-continuation.ts";
22	import type { Session } from "../../domain/work/session.ts";
23	import { defineScript } from "./lib/script-ref.ts";
24	
25	export interface InjectLoopContinuationArgs {
26	  session: string;
27	}
28	
29	export const ref = defineScript<InjectLoopContinuationArgs>(import.meta.url);
30	
31	function main(): void {
32	  const { values } = parseArgs({
33	    args: Bun.argv.slice(2),
34	    options: { session: { type: "string" } },
35	  });
36	  const path = values.session;
37	  if (!path) {
38	    console.error("usage: inject_loop_continuation.ts --session PATH");
39	    process.exit(2);
40	  }
41	  if (!existsSync(path)) {
42	    console.error(`inject_loop_continuation: ${path} does not exist; nothing to do`);
43	    return;
44	  }
45	
46	  const session = JSON.parse(readFileSync(path, "utf8")) as Session;
47	  const abort = loopAbortFromSession(session);
48	  if (abort === undefined) {
49	    console.error(`inject_loop_continuation: ${path} records no loop verdict; nothing to say`);
50	    return;
51	  }
52	  const messages = session.messages ?? [];
53	  messages.push({ role: "user", content: loopContinuationMessage(abort) });
54	  session.messages = messages;
55	  writeFileSync(path, JSON.stringify(session, null, 2));
